import json

with open('/app/output/data_analysis.json') as f:
    d = json.load(f)

def fmt(n, decimals=1):
    if n is None:
        return "N/A"
    if isinstance(n, float):
        return f"{n:,.{decimals}f}"
    return f"{n:,}"

def pct_str(n):
    if n is None:
        return "N/A"
    return f"{n:.1f}%"

years = sorted([int(k) for k in d['risk_trend'].keys()])
risk_vals = [d['risk_trend'][str(y)] for y in years]
salary_vals = [d['salary_trend'][str(y)] for y in years]
survival_rates = [d['survival_trend'][str(y)]['survival_rate'] for y in years]
strong_rates = [d['survival_trend'][str(y)]['strong_rate'] for y in years]
openings_vals = [d['openings_trend'][str(y)] for y in years]

