<body>
<div class="report-container">

<!-- ═══════════ HERO ═══════════ -->
<header class="hero">
  <h1>AI Impact on the Global Job Market</h1>
  <p class="subtitle">Risk, Salary &amp; Skills Trend Analysis (2015–2035)</p>
  <p class="subtitle">{d['overview']['one_liner'] if 'one_liner' in d['overview'] else "A comprehensive trend analysis examining how AI automation risk, salary dynamics, skill demand, and job survival prospects are evolving across roles, countries, and experience levels."}</p>
  <p class="meta">Dataset: {d['overview']['total_rows']:,} records · {d['overview']['num_job_titles']} job titles · {d['overview']['num_countries']} countries · {d['overview']['year_range']} · Generated May 7, 2026</p>
</header>

<!-- ═══════════ KPI BANNER ═══════════ -->
<div class="kpi-banner">
  <div class="kpi-card">
    <div class="kpi-value">{d['highlights']['overall_survival_rate']}%</div>
    <div class="kpi-label">Overall Job Survival Rate</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">+{fmt(d['highlights']['risk_change_2015_2035'], 0)}%</div>
    <div class="kpi-label">AI Risk Score Increase</div>
    <div class="kpi-delta up">2015 → 2035</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{d['highlights']['salary_risk_correlation']}</div>
    <div class="kpi-label">Salary–Risk Correlation</div>
    <div class="kpi-delta down">Strong negative</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{d['highlights']['fastest_skill']}</div>
    <div class="kpi-label">Fastest-Growing Skill</div>
    <div class="kpi-delta up">+{fmt(d['highlights']['fastest_skill_gain'], 0)} pts</div>
  </div>
  <div class="kpi-card">
