    </div>
    <div class="chart-box">
      <h4>Risk Score by Experience Level</h4>
      <div class="chart-wrap"><canvas id="chartRiskByExp"></canvas></div>
    </div>
  </div>

  <div class="chart-box">
    <h4>AI Risk Category Distribution</h4>
    <div class="chart-wrap" style="max-width:500px; margin:0 auto;"><canvas id="chartRiskCat"></canvas></div>
  </div>

  <div class="card-grid" style="margin-top:20px;">
    <div class="card">
      <h4>Highest-Risk Jobs (Top 5)</h4>
      <table class="data-table" style="margin-top:8px;">
        <thead><tr><th>Job Title</th><th class="num">Mean Risk</th><th class="num">Std Dev</th></tr></thead>
        <tbody>'''

for job, vals in d['top_risk_jobs'].items():
    html += f'<tr><td>{job}</td><td class="num"><span class="badge badge-red">{vals["mean"]}</span></td><td class="num">{vals["std"]}</td></tr>'

