def fmt(n, decimals=1):
    if n is None:
        return "N/A"
    if isinstance(n, float):
        return f"{n:,.{decimals}f}"
    return f"{n:,}"

def pct_str(n):
    if n is None:
        return "N/A"
    return f"{n:.1f}%"

